import { z } from "zod";
import { rpcErrorMessage } from "./stockRecipe.ts";

/** Pure validation and result mapping for the `create_stock_item` RPC (SKU is generated by the database). */

export type StockItemOrigin = "workshop" | "purchased";

export interface CreateStockItemInput {
  origin: StockItemOrigin;
  name: string;
  description: string | null;
  unit: string;
  /** Id of the workshop base item this one is a variant of; null for a new base. */
  variantOf: string | null;
}

const blankToUndefined = (v: unknown) => (typeof v === "string" && v.trim() === "" ? undefined : v);

const schema = z.object({
  origin: z.enum(["workshop", "purchased"], { error: "Elige el origen del insumo." }),
  name: z.string().trim().min(1, "El nombre es obligatorio."),
  description: z.preprocess(blankToUndefined, z.string().trim().optional()),
  unit: z.string().trim().min(1, "La unidad es obligatoria.").max(20),
  variantOf: z.preprocess(blankToUndefined, z.string().uuid("El insumo base no es válido.").optional()),
});

export function parseCreateStockItemInput(
  raw: Record<string, unknown>,
): { ok: true; data: CreateStockItemInput } | { ok: false; error: string } {
  const parsed = schema.safeParse(raw);
  if (!parsed.success) return { ok: false, error: parsed.error.issues[0]?.message ?? "Datos inválidos." };
  const { origin, name, description, unit, variantOf } = parsed.data;
  if (origin === "purchased" && variantOf) {
    return { ok: false, error: "Un insumo comprado no puede ser variante de otro." };
  }
  return { ok: true, data: { origin, name, unit, description: description || null, variantOf: variantOf ?? null } };
}

export function mapCreateStockItemResult(res: {
  ok: boolean;
  error?: string;
  mensaje?: string;
  [key: string]: unknown;
}): { ok: true; sku: string; stockItemId: string } | { ok: false; error: string } {
  if (!res.ok) return { ok: false, error: rpcErrorMessage(res.error, res.mensaje) };
  if (typeof res.sku !== "string" || !res.sku) return { ok: false, error: rpcErrorMessage(undefined) };
  if (typeof res.stock_item_id !== "string" || !res.stock_item_id) {
    return { ok: false, error: rpcErrorMessage(undefined) };
  }
  return { ok: true, sku: res.sku, stockItemId: res.stock_item_id };
}

export interface VariantBaseOption {
  id: string;
  sku: string;
  name: string;
}

function fold(value: string): string {
  return value.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

/**
 * Bases candidatas para una variante: cada palabra de la búsqueda debe
 * aparecer en el SKU o el nombre (sin distinguir tildes ni mayúsculas).
 * Una búsqueda vacía no devuelve nada: la lista solo aparece al escribir.
 */
export function filterVariantBases(
  options: VariantBaseOption[],
  query: string,
  limit = 8,
): VariantBaseOption[] {
  const words = fold(query).split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];
  return options
    .filter((o) => {
      const haystack = fold(`${o.sku} ${o.name}`);
      return words.every((w) => haystack.includes(w));
    })
    .slice(0, limit);
}
